B.afK=new A.ax("ko-g1",B.aK,"culture","\ubc30\uc591\uc2e4 \ub9e4\uc77c \uc810\uac80",10,B.eS,B.a1O,"\ud770 \uade0\uc774 \ubcd1 \uc704\ucabd\uc5d0\uc11c \uc544\ub798\ucabd\uc73c\ub85c \uace0\ub974\uac8c \ud37c\uc838 \uac00\uc694.","\uc0c9\uc774 \ub2e4\ub978 \uc5bc\ub8e9\uc774 \uc788\ub294 \ubcd1\uc740 \ub2e4\ub978 \ubcd1\uacfc \ub5a8\uc5b4\ub728\ub9ac\uace0 \uc0ac\uc9c4\uc744 \ub0a8\uae34 \ub4a4, \uc624\uc5fc\uc774 \ud655\uc2e4\ud558\uba74 \uce58\uc6cc\uc694.",B.o,B.aj,1,"\ud770 \uade0\uc774 \ud37c\uc9c4 \ubcd1\uacfc \uc5bc\ub8e9\uc774 \uc0dd\uae34 \ubcd1 \ube44\uad50 \uc0ac\uc9c4")
B.XA=s(["\ubcd1 \uc804\uccb4\uac00 \ud770 \uade0\uc73c\ub85c \ub36e\uc600\ub294\uc9c0 \ud655\uc778\ud574\uc694(\uc790\ub8cc: \uc811\uc885 \ud6c4 35~40\uc77c\ucbe4).","\ub2e4 \ub36e\uc600\uc73c\uba74 \ubc30\uc591\uc2e4\uc5d0 5~10\uc77c \ub354 \ub46c\uc694(\ud6c4\uc219). \ubc84\uc12f\uc774 \ub354 \uace0\ub974\uac8c \uc790\ub77c\uc694."],t.s)
B.ag1=new A.ax("ko-g2",B.aK,"culture","\ubc30\uc591\uc774 \ub05d\ub0ac\ub294\uc9c0 \ud655\uc778\ud558\uace0 \ud6c4\uc219\ud558\uae30",20,B.ir,B.XA,"\ubcd1 \uc544\ub798\uae4c\uc9c0 \ud770 \uade0\uc774 \uac00\ub4dd\ud574\uc694.","\uc544\uc9c1 \ub35c \ub36e\uc600\uc73c\uba74 \uba70\uce60 \ub354 \ub450\uace0 \uae30\ub2e4\ub824\uc694. \ub0a0\uc9dc\ub9cc \ubcf4\uace0 \ub2e4\uc74c\uc73c\ub85c \ub118\uae30\uc9c0 \uc54a\uc544\uc694.",B.o,B.aj,-1,null)
B.a1D=s(["\uade0 \uae01\uae30 \ub3c4\uad6c","\uba78\uade0\uc218","\uc7a5\uac11"],t.s)
B.adD=s(["\ubcd1 \uc717\ubd80\ubd84\uc758 \uc624\ub798\ub41c \uade0\uc744 \uae01\uc5b4\ub0b4\uc694(\uade0 \uae01\uae30).","\uae01\uc740 \ub4a4 \ubc14\ub85c \uba78\uade0\uc218\ub97c \uc918\uc11c \ud45c\uba74\uc774 \ub9c8\ub974\uc9c0 \uc54a\uac8c \ud574\uc694. \ubb3c\uc758 \uc591\uc740 \uc790\ub8cc\uc5d0 \uc22b\uc790\uac00 \uc5c6\uc5b4\uc694.","\ubcd1\uc744 \ubc1c\uc774\uc2e4(\uc628\ub3c4 14~16\u2103, \uc2b5\ub3c4 90% \uc774\uc0c1)\ub85c \uc62e\uaca8\uc694."],t.s)
