B.a32=s(["\uba78\uade0\uc774 \ub35c \ub410\uac70\ub098 \uc811\uc885\ud560 \ub54c \uc7a1\uade0\uc774 \ub4e4\uc5b4\uac14\uc744 \uc218 \uc788\uc5b4\uc694.","\ubc30\uc591\uc2e4 \uc628\ub3c4\uac00 \ub108\ubb34 \ub192\uac70\ub098 \uacf5\uae30\uac00 \uae68\ub057\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\uc5b4\uc694."],t.s)
B.adG=s(["\uc5bc\ub8e9\uc774 \ud55c \ubcd1\ubfd0\uc778\uc9c0 \uc5ec\ub7ec \ubcd1\uc778\uc9c0 \ubd10\uc694.","\uac19\uc740 \ub0a0 \uc811\uc885\ud55c \ubcd1\uc774\ub098 \uac19\uc740 \uc904\uc5d0\uc11c\ub9cc \uc0dd\uae30\ub294\uc9c0 \ubd10\uc694.","\ubc30\uc591\uc2e4 \uc628\ub3c4\uac00 20~22\u2103\uc778\uc9c0 \uae30\ub85d\uc744 \ud655\uc778\ud574\uc694."],t.s)
