B.a4e=s(["\uc78e\uc774 \ucd95 \ucc98\uc9c0\uace0 \ub05d\uc774 \ub9c8\ub974\uac70\ub098 \ub9d0\ub824\uc694(\uc78e\ub05d \ub9c8\ub984 \uc704\ud5d8).","\uc0dd\uc721\uc774 \ub290\ub9ac\uace0 \uc78e\uc774 \uc791\uc544\uc838\uc694.","\ud759 \ud45c\uba74\uc774 \ud558\uc597\uac8c \ub9c8\ub974\uace0 \uac08\ub77c\uc838\uc694."],t.s)
B.adE=s(["\uc78e\uc774 \ub204\ub807\uac8c \ub418\uace0 \ubfcc\ub9ac\uac00 \uac08\uc0c9\uc73c\ub85c \ubb3c\ub7ec\uc838\uc694.","\ud759\uc774 \uc9c8\ucc99\ud558\uace0 \uacf0\ud321\uc774\xb7\ubb34\ub984\ubcd1\uc774 \uc0dd\uaca8\uc694.","\uacfc\uc2b5\uacfc \uac74\uc870\uac00 \ubc18\ubcf5\ub418\uba74 \uc78e \ub05d\uc774 \ub9c8\ub97c \uc218 \uc788\uc5b4\uc694(\uc790\ub8cc)."],t.s)
B.a_9=s(["\uc190\uac00\ub77d\uc744 \ud759\uc5d0 2~3cm \ub123\uc5b4 \ubd10\uc694. \ucd09\ucd09\ud558\uba74 \ucda9\ubd84\ud574\uc694(\uc77c\ubc18 \uc694\ub839).","\uc544\uce68\uc5d0 \uc78e\uc774 \ud0f1\ud0f1\ud55c\uc9c0 \ubd10\uc694.","\ud759 \ud45c\uba74 \uc0c9(\uc9c4\ud55c \uac08\uc0c9 = \ucd09\ucd09, \uc5f0\ud55c \uc0c9 = \ub9c8\ub984)\uc744 \ub9e4\uc77c \uac19\uc740 \uc2dc\uac04\uc5d0 \ube44\uad50\ud574\uc694."],t.s)
B.aAy=new A.qm("\uc78e\ucc44\uc18c\ub294 \ud759\uc774 \ub9c8\ub974\uc9c0 \uc54a\uac8c \ud558\ub294 \uac83\uc774 \uae30\ubcf8\uc774\uc5d0\uc694. \uc544\ub798 \uac04\uaca9\uc740 \uc0c1\ucd94 \uc790\ub8cc(\ud143\ubc2d\xb7\ub178\uc9c0 \uae30\uc900)\ub77c\uc11c, \uc2dc\uc124\xb7\ubca0\ub4dc\xb7\uc218\uacbd\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5b4\uc694.",B.a4g,"\uc624\uc804(06~11\uc2dc): \ud759 \ud45c\uba74\uc744 \ubcf4\uace0 \uc624\ub298 \uc904\uc9c0 \uc815\ud574\uc694. \uc904 \ub54c\ub294 \ub0ae\uc774 \ub418\uae30 \uc804\uc5d0 \ub9c8\uccd0\uc11c \uc78e\uc774 \ub9c8\ub974\uac8c \ud574\uc694(\uc77c\ubc18 \uc694\ub839).","\uc624\ud6c4(14~18\uc2dc): \ud55c\ub0ae\uc774 \uc9c0\ub09c \ub4a4 \uc2dc\ub4dc\ub294 \ud3ec\uae30\uac00 \uc788\ub294\uc9c0 \ud655\uc778\ud574\uc694. \ub2a6\uc740 \uc624\ud6c4 \uae09\uc218\ub294 \uc78e\uc774 \uc816\uc740 \ucc44 \ubc24\uc744 \ub9de\uac8c \ud558\ub2c8 \ud53c\ud574\uc694(\uc77c\ubc18 \uc694\ub839).",B.a4e,B.adE,B.a_9,"\uac04\uaca9\uc740 \ud143\ubc2d \uae30\uc900\uc774\uc5d0\uc694. \ubca0\ub4dc\xb7\ubc30\uc9c0\xb7\uc218\uacbd \uc7ac\ubc30\uc5d0\uc11c\ub294 \ubc30\uc9c0\uac00 \ub9c8\ub974\ub294 \uc18d\ub3c4\uac00 \ub2ec\ub77c\uc694. \ubb3c\uc758 \uc591\uc740 \uc790\ub8cc\uc5d0 \uc5c6\uc5b4 \uc22b\uc790\ub97c \uc801\uc9c0 \uc54a\uc558\uc5b4\uc694.")
